using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class ShiftCalendarTests
{
 class User:ICurrentUser{public string Email=>"shift@example.local";public int? EmployeeId=>6;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>true;public bool Can(string p)=>true;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 [Fact]public void DatedOverridePrecedesEffectiveAssignmentAndCurrentDefault(){var e=new Employee{Id=6,ShiftId=1};var h=new[]{new EmployeeAssignment{EmployeeId=6,ShiftId=2,EffectiveFrom=new(2026,11,1),EffectiveTo=new(2026,12,1)}};var o=new[]{new EmployeeShiftDay{EmployeeId=6,ShiftId=3,Date=new(2026,11,24)}};Assert.Equal(3,ShiftCalendar.ShiftId(e,new(2026,11,24),h,o));Assert.Equal(2,ShiftCalendar.ShiftId(e,new(2026,11,23),h,o));Assert.Equal(1,ShiftCalendar.ShiftId(e,new(2026,12,1),h,o));}
 [Fact]public void OvernightDateAndManualOutAreExplicit(){var s=new Shift{Start=new(22,0,0),End=new(6,0,0)};var d=new DateTime(2026,11,23);Assert.Equal(d,ShiftCalendar.WorkDate(d.AddDays(1).AddHours(6),s));Assert.Equal(d.AddDays(1),ShiftCalendar.WorkDate(d.AddDays(1).AddHours(9),s));Assert.Equal(d.AddDays(1).AddHours(6),ShiftCalendar.OvernightOut(d,d.AddHours(22),d.AddHours(6),s));}
 [Fact]public async Task DeviceNightPunchesPairAcrossMidnightWithoutChangingRawTime(){await using var d=await Db();var u=new User();var c=new AppClock(TimeProvider.System);var e=(await d.Set<Employee>().FindAsync(6))!;var shift=new Shift{Name="Night test",Start=new(22,0,0),End=new(6,0,0)};d.Add(shift);await d.SaveAsync();e.ShiftId=shift.Id;await d.SaveAsync();var day=new DateTime(2026,10,2);var svc=new DeviceService(d,c,new AuditService(d,u,c),u);await svc.IngestAsync(new[]{new DeviceService.PunchIn(e.Code,day.AddHours(22)),new DeviceService.PunchIn(e.Code,day.AddDays(1).AddHours(6))});var rec=await d.Set<AttendanceRecord>().SingleAsync(x=>x.EmployeeId==6&&x.Date==day);Assert.Equal(day.AddDays(1).AddHours(6),rec.CheckOut);Assert.Equal(480,rec.WorkedMinutes);Assert.Equal(2,await d.Set<DevicePunch>().CountAsync());}
 [Fact]public async Task DatedScheduleUpdatesAreAuditedAndUnique(){await using var d=await Db();var u=new User();var c=new AppClock(TimeProvider.System);var s=new ShiftSchedule(d,u,c,new AuditService(d,u,c));var shift=(await d.Set<Shift>().FirstAsync()).Id;var day=c.Today.AddDays(1);await s.SetAsync(6,day,shift,"First plan");await s.SetAsync(6,day,shift,"Reviewed plan");Assert.Single(await d.Set<EmployeeShiftDay>().ToListAsync());Assert.Equal("Reviewed plan",(await d.Set<EmployeeShiftDay>().SingleAsync()).Reason);Assert.Equal(2,await d.Set<AuditLog>().CountAsync(x=>x.Action=="ScheduleShift"));}
}
